const container=document.getElementById("gradient_Div"),hoverText=document.getElementById("gradient_Hover"),gradientOverlay=document.getElementById("gradient_Bg"),textContent=document.getElementById("gradient_Text");let isHovered=!1;hoverText.addEventListener("mouseenter",()=>{isHovered||(container.classList.add("active"),textContent.textContent="Human-Powered Everything.",isHovered=!0)}),hoverText.addEventListener("mouseleave",()=>{container.classList.remove("active"),textContent.textContent="Swiss-Engineered Nothing.",isHovered=!1});